import type { Selection } from '@gentleduck/calendar'
import type * as React from 'react'
import type { ICalendarProps, ICalendarSelectionValue } from './calendar.types'

const MAX_CACHE_SIZE = 20

/** Cache Intl.NumberFormat instances to avoid recreating formatters on every render. */
const NUMBER_FORMAT_CACHE = new Map<string, Intl.NumberFormat>()

export function callCalendarSelectHandler(
  mode: Selection.SelectionMode,
  onSelect: NonNullable<ICalendarProps['onSelect']>,
  value: ICalendarSelectionValue,
) {
  switch (mode) {
    case 'range':
      return (onSelect as NonNullable<ICalendarProps.IRange['onSelect']>)(value as ICalendarSelectionValue<'range'>)
    case 'multi':
      return (onSelect as NonNullable<ICalendarProps.IMulti['onSelect']>)(value as ICalendarSelectionValue<'multi'>)
    case 'multi-range':
      return (onSelect as NonNullable<ICalendarProps.IMultiRange['onSelect']>)(
        value as ICalendarSelectionValue<'multi-range'>,
      )
    case 'single':
      return (onSelect as NonNullable<ICalendarProps.ISingle['onSelect']>)(value as ICalendarSelectionValue<'single'>)
  }
}

export function getCachedNumberFormat(locale: string, options?: Intl.NumberFormatOptions): Intl.NumberFormat {
  const key = options ? `${locale}|${JSON.stringify(options)}` : locale
  let fmt = NUMBER_FORMAT_CACHE.get(key)
  if (fmt) {
    // LRU: move to end
    NUMBER_FORMAT_CACHE.delete(key)
    NUMBER_FORMAT_CACHE.set(key, fmt)
    return fmt
  }
  // Evict oldest if at capacity
  if (NUMBER_FORMAT_CACHE.size >= MAX_CACHE_SIZE) {
    for (const oldest of NUMBER_FORMAT_CACHE.keys()) {
      NUMBER_FORMAT_CACHE.delete(oldest)
      break
    }
  }
  fmt = new Intl.NumberFormat(locale, options)
  NUMBER_FORMAT_CACHE.set(key, fmt)
  return fmt
}

// The ones and tens, each a letter, for the days of a month: 1 to 31.
const HEBREW_ONES = '\u05D0\u05D1\u05D2\u05D3\u05D4\u05D5\u05D6\u05D7\u05D8'
const HEBREW_TENS = '\u05D9\u05DB\u05DC'

/** A day of the month in Hebrew numerals: one letter takes a geresh, two take a gershayim before the last. */
export function toHebrewNumeral(day: number): string {
  // 15 and 16 are written 9 + 6 and 9 + 7, since 10 + 5 and 10 + 6 spell the name of God.
  if (day === 15) return '\u05D8\u05F4\u05D5'
  if (day === 16) return '\u05D8\u05F4\u05D6'
  const tens = HEBREW_TENS.charAt(Math.floor(day / 10) - 1)
  const ones = HEBREW_ONES.charAt((day % 10) - 1)
  return tens && ones ? `${tens}\u05F4${ones}` : `${tens}${ones}\u05F3`
}

export function formatDayNumber(day: number, locale?: string): React.ReactNode {
  if (!locale) return day
  if (locale.startsWith('ar')) return getCachedNumberFormat(`${locale}-u-nu-arab`).format(day)
  if (locale.startsWith('he')) return toHebrewNumeral(day)
  return getCachedNumberFormat(locale).format(day)
}

'use client'

import { NativeAdapter, useCalendar } from '@gentleduck/calendar'
import { cn } from '@gentleduck/libs/cn'
import { useDirection } from '@gentleduck/primitives/direction'
import { ChevronLeftIcon, ChevronRightIcon } from 'lucide-react'
import * as React from 'react'
import { buttonVariants } from '../button'
import { callCalendarSelectHandler, getCachedNumberFormat } from './calendar.libs'
import type { ICalendarProps } from './calendar.types'
import { CalendarDayCell } from './calendar-day'
import { CalendarHeader } from './calendar-header'

const DEFAULT_ADAPTER = new NativeAdapter()

const Calendar = React.forwardRef<HTMLDivElement, ICalendarProps>(
  (
    {
      className,
      adapter = DEFAULT_ADAPTER,
      buttonVariant = 'ghost',
      mode = 'single',
      selected,
      onSelect,
      disabled,
      defaultMonth,
      month: controlledMonth,
      onMonthChange,
      showOutsideDays = true,
      fixedWeeks = false,
      numberOfMonths = 1,
      locale,
      dir,
      fromDate,
      toDate,
      onDismiss,
      weekStartDay,
      showWeekNumber = false,
      pageBehavior,
      unavailable,
      readOnly,
      invalid,
      showDropdowns = true,
      yearRange,
      renderDay,
      renderHeader,
      renderWeekday,
      renderFooter,
    },
    ref,
  ) => {
    const direction = useDirection(dir)
    const currentYear = new Date().getFullYear()
    const resolvedYearRange = yearRange ?? { from: currentYear - 100, to: currentYear + 10 }
    // Arabic uses Eastern Arabic numerals via `-u-nu-arab` extension
    const formatLocale = locale?.startsWith('ar') ? `${locale}-u-nu-arab` : locale

    const calendar = useCalendar({
      adapter,
      mode,
      locale: { locale, weekStartDay, direction },
      month: controlledMonth,
      defaultMonth,
      selected,
      onSelect: onSelect ? (value) => callCalendarSelectHandler(mode, onSelect, value) : undefined,
      onMonthChange,
      showOutsideDays,
      fixedWeeks,
      numberOfMonths,
      disabled,
      fromDate,
      toDate,
      onDismiss,
      pageBehavior,
      unavailable,
      readOnly,
      invalid,
    })

    const { state, getDayProps, getGridProps, getNavProps, getHeaderProps, announcer } = calendar

    // Only show focus ring during keyboard navigation, not on mouse clicks
    const [keyboardActive, setKeyboardActive] = React.useState(false)

    const prevNavProps = getNavProps('prev')
    const nextNavProps = getNavProps('next')

    return (
      // biome-ignore lint/a11y/noStaticElementInteractions: keyboard/pointer tracking for focus ring management
      <div
        ref={ref}
        data-slot="calendar"
        dir={direction}
        onKeyDown={() => {
          if (!keyboardActive) setKeyboardActive(true)
        }}
        onPointerDown={() => {
          if (keyboardActive) setKeyboardActive(false)
        }}
        className={cn(
          'group/calendar w-fit bg-background p-3 [--gentleduck-calendar-cell:--spacing(8)]',
          'rounded-md in-data-[slot=card-content]:bg-transparent in-data-[slot=popover-content]:bg-transparent',
          className,
        )}>
        <div className="relative flex flex-col gap-4">
          {renderHeader ? (
            renderHeader({
              month: state.month,
              title: adapter.format(state.month, { month: 'long', year: 'numeric' }, formatLocale),
              direction,
              goToPrevMonth: prevNavProps.onClick,
              goToNextMonth: nextNavProps.onClick,
              isPrevDisabled: prevNavProps.disabled,
              isNextDisabled: nextNavProps.disabled,
            })
          ) : numberOfMonths <= 1 ? (
            <CalendarHeader
              adapter={adapter}
              month={state.month}
              title={adapter.format(state.month, { month: 'long', year: 'numeric' }, formatLocale)}
              direction={direction}
              locale={locale}
              buttonVariant={buttonVariant}
              showDropdowns={showDropdowns}
              yearRange={resolvedYearRange}
              getNavProps={getNavProps}
              getHeaderProps={getHeaderProps}
              onMonthSelect={calendar.actions.setMonth}
            />
          ) : (
            <div className="relative flex w-full items-center">
              <button
                type="button"
                {...prevNavProps}
                className={cn(
                  buttonVariants({ variant: buttonVariant as 'ghost' }),
                  'absolute start-0 z-10 size-(--gentleduck-calendar-cell) select-none p-0 aria-disabled:cursor-not-allowed aria-disabled:opacity-50',
                )}>
                <ChevronLeftIcon className={cn('size-4', direction === 'rtl' && 'rotate-180')} />
              </button>
              {state.months.map((m) => (
                <span key={m.month.getTime()} className="flex-1 select-none text-center font-medium text-sm">
                  {adapter.format(m.month, { month: 'long', year: 'numeric' }, formatLocale)}
                </span>
              ))}
              <button
                type="button"
                {...nextNavProps}
                className={cn(
                  buttonVariants({ variant: buttonVariant as 'ghost' }),
                  'absolute end-0 z-10 size-(--gentleduck-calendar-cell) select-none p-0 aria-disabled:cursor-not-allowed aria-disabled:opacity-50',
                )}>
                <ChevronRightIcon className={cn('size-4', direction === 'rtl' && 'rotate-180')} />
              </button>
            </div>
          )}

          <div className="flex flex-col gap-4 md:flex-row">
            {state.months.map((monthGrid) => {
              const gridProps = getGridProps()
              return (
                <div key={monthGrid.month.getTime()} className="flex w-full flex-col gap-4">
                  <div {...gridProps}>
                    {/* biome-ignore lint/a11y/useSemanticElements: role="row" on div per WAI-ARIA grid pattern */}
                    {/* biome-ignore lint/a11y/useFocusableInteractive: weekday header row is not interactive */}
                    <div role="row" className="flex">
                      {showWeekNumber && <div aria-hidden="true" className="w-(--gentleduck-calendar-cell) shrink-0" />}
                      {state.weekdays.map((day, index) => (
                        // biome-ignore lint/a11y/useSemanticElements: columnheader on div per WAI-ARIA grid pattern
                        // biome-ignore lint/a11y/useFocusableInteractive: weekday headers are not interactive
                        <div
                          key={day}
                          role="columnheader"
                          className="flex-1 select-none rounded-md text-center font-normal text-[0.8rem] text-muted-foreground">
                          {renderWeekday
                            ? renderWeekday(day, index)
                            : locale?.startsWith('ar')
                              ? day.replace(/^ال/, '')
                              : locale?.startsWith('fa')
                                ? day.slice(0, 2)
                                : locale?.startsWith('he')
                                  ? day.replace(/^יום\s*/, '')
                                  : day}
                        </div>
                      ))}
                    </div>
                    {monthGrid.weeks.map((week) => (
                      // biome-ignore lint/a11y/useSemanticElements: role="row" on div per WAI-ARIA grid pattern
                      // biome-ignore lint/a11y/useFocusableInteractive: grid rows are not interactive
                      <div key={week.weekNumber} role="row" className="mt-2 flex w-full">
                        {showWeekNumber && (
                          // biome-ignore lint/a11y/useSemanticElements: rowheader on div per WAI-ARIA grid pattern
                          // biome-ignore lint/a11y/useFocusableInteractive: a week number is read, never focused
                          <div
                            role="rowheader"
                            aria-label={`Week ${week.weekNumber}`}
                            className="flex w-(--gentleduck-calendar-cell) shrink-0 select-none items-center justify-center text-[0.8rem] text-muted-foreground">
                            {formatLocale
                              ? getCachedNumberFormat(formatLocale).format(week.weekNumber)
                              : week.weekNumber}
                          </div>
                        )}
                        {week.days.map((day, dayIdx) => {
                          const {
                            onMouseEnter: _,
                            role: _role,
                            'aria-selected': _ariaSel,
                            ...dayProps
                          } = getDayProps(day)
                          const isSelectedSingle =
                            day.isSelected && !day.isRangeStart && !day.isRangeEnd && !day.isRangeMiddle
                          const isFocused = keyboardActive && dayProps['data-focused'] === 'true'
                          return (
                            <CalendarDayCell
                              key={day.date.getTime()}
                              day={day}
                              dayProps={dayProps}
                              isFocused={isFocused}
                              isSelectedSingle={isSelectedSingle}
                              isFirstInRow={dayIdx === 0}
                              isLastInRow={dayIdx === 6}
                              locale={locale}
                              onFocusDate={(date) => {
                                setKeyboardActive(false)
                                calendar.actions.focusDate(date)
                              }}
                              renderDay={renderDay}
                            />
                          )
                        })}
                      </div>
                    ))}
                  </div>
                </div>
              )
            })}
          </div>
          {renderFooter?.(state.months)}
        </div>
        <announcer.AnnouncerPortal />
      </div>
    )
  },
)
Calendar.displayName = 'Calendar'

export { Calendar }

import type { Adapter, Grid, Selection, UseCalendar } from '@gentleduck/calendar'
import type { IDirection } from '@gentleduck/primitives/direction'
import type { Button, ButtonProps } from '../button'

export interface ICalendarHeaderContext {
  /** The current displayed month Date. */
  month: Date
  /** Formatted title string (e.g. "March 2026"). */
  title: string
  /** Resolved text direction. */
  direction: 'ltr' | 'rtl'
  /** Navigate to the previous month. */
  goToPrevMonth: () => void
  /** Navigate to the next month. */
  goToNextMonth: () => void
  /** Whether previous navigation is disabled. */
  isPrevDisabled: boolean
  /** Whether next navigation is disabled. */
  isNextDisabled: boolean
}

export interface ICalendarHeaderProps {
  adapter: Adapter.IDateAdapter<Date>
  month: Date
  title: string
  direction: 'ltr' | 'rtl'
  locale?: string
  buttonVariant: ButtonProps['variant']
  showDropdowns: boolean
  yearRange: { from: number; to: number }
  getNavProps: (dir: 'prev' | 'next') => { 'aria-label': string; disabled: boolean; onClick: () => void }
  getHeaderProps: () => { id: string; 'aria-live': 'polite' }
  onMonthSelect: (date: Date) => void
}

export interface ICalendarDayCellProps {
  day: Grid.ICalendarDay<Date>
  dayProps: Omit<UseCalendar.IDayProps, 'role' | 'aria-selected' | 'onMouseEnter'>
  isFocused: boolean
  isSelectedSingle: boolean
  isFirstInRow: boolean
  isLastInRow: boolean
  locale?: string
  onFocusDate: (date: Date) => void
  renderDay?: (day: Grid.ICalendarDay<Date>, children: React.ReactNode) => React.ReactNode
}

export type ICalendarSelectionValue<TMode extends Selection.SelectionMode = Selection.SelectionMode> =
  Selection.CalendarValue<Date, TMode>

export type ICalendarProps =
  | ICalendarProps.ISingle
  | ICalendarProps.IRange
  | ICalendarProps.IMulti
  | ICalendarProps.IMultiRange

export namespace ICalendarProps {
  export interface IBase {
    className?: string
    /**
     * Date adapter for alternative calendar systems (Islamic, Persian, etc.).
     * Default uses `NativeAdapter` (Gregorian).
     */
    adapter?: Adapter.IDateAdapter<Date>
    /** Variant style for navigation buttons. Default `'ghost'`. */
    buttonVariant?: React.ComponentProps<typeof Button>['variant']
    /** Dates that cannot be selected. */
    disabled?: Date[] | ((date: Date) => boolean)
    /** Default month to display (uncontrolled). */
    defaultMonth?: Date
    /** Controlled month. */
    month?: Date
    /** Called when the displayed month changes. */
    onMonthChange?: (month: Date) => void
    /** Show days from adjacent months. Default `true`. */
    showOutsideDays?: boolean
    /** Always show 6 weeks. Default `false`. */
    fixedWeeks?: boolean
    /** How many months to show side by side. Default `1`. */
    numberOfMonths?: number
    /** BCP 47 locale tag (e.g. `'ar-SA'`). */
    locale?: string
    /** Text direction. */
    dir?: IDirection.Kind
    /** Earliest selectable date. */
    fromDate?: Date
    /** Latest selectable date. */
    toDate?: Date
    /** Called when the user presses Escape. */
    onDismiss?: () => void
    /** First day of the week, 0 for Sunday. Defaults to the locale's first day, or Sunday with no locale. */
    weekStartDay?: Adapter.WeekStartDay
    /** Starts each week with its ISO week number. Default `false`. */
    showWeekNumber?: boolean
    /**
     * With several months shown, whether the nav buttons and PageUp/PageDown move one month (`'single'`)
     * or the whole view (`'visible'`). Default `'single'`.
     */
    pageBehavior?: 'single' | 'visible'
    /** Dates that stay focusable but cannot be picked, such as booked days. A range cannot span one. */
    unavailable?: Date[] | ((date: Date) => boolean)
    /** Keeps the selection as it is, while the keys still move focus. */
    readOnly?: boolean
    /** Marks the selection invalid. A selection holding a day that cannot be picked is invalid without it. */
    invalid?: boolean
    /**
     * Show month and year dropdowns in the header.
     * Default `true`. Set to `false` for a minimal caption.
     */
    showDropdowns?: boolean
    /**
     * Range of years to show in the year dropdown.
     * Default `{ from: currentYear - 100, to: currentYear + 10 }`.
     */
    yearRange?: { from: number; to: number }
    /**
     * Custom render function for day cells.
     * Receives the day object and the default rendered children (the date number).
     * Return a ReactNode to replace or wrap the default content.
     *
     * @example
     * ```tsx
     * renderDay={(day, children) => (
     *   <>
     *     {children}
     *     {hasEvents(day.date) && <span className="size-1 rounded-full bg-primary" />}
     *   </>
     * )}
     * ```
     */
    renderDay?: (day: Grid.ICalendarDay<Date>, children: React.ReactNode) => React.ReactNode
    /**
     * Custom render function for the navigation header.
     * Receives header context with month info and navigation controls.
     * Return a ReactNode to replace the default header entirely.
     *
     * @example
     * ```tsx
     * renderHeader={({ title, goToPrevMonth, goToNextMonth }) => (
     *   <div className="flex items-center justify-between">
     *     <button onClick={goToPrevMonth}><-</button>
     *     <span>{title}</span>
     *     <button onClick={goToNextMonth}>-></button>
     *   </div>
     * )}
     * ```
     */
    renderHeader?: (context: ICalendarHeaderContext) => React.ReactNode
    /**
     * Custom render function for weekday column headers.
     * Receives the weekday abbreviation (e.g. "Sun") and its index (0-6).
     * Return a ReactNode to replace the default weekday label.
     *
     * @example
     * ```tsx
     * renderWeekday={(day, index) => (
     *   <span className={index === 0 || index === 6 ? 'text-red-500' : ''}>
     *     {day}
     *   </span>
     * )}
     * ```
     */
    renderWeekday?: (day: string, index: number) => React.ReactNode
    /**
     * Render content below the calendar grid.
     * Receives the current months array for context.
     *
     * @example
     * ```tsx
     * renderFooter={(months) => (
     *   <div className="mt-2 text-xs text-muted-foreground">
     *     Selected: {selected?.toLocaleDateString()}
     *   </div>
     * )}
     * ```
     */
    renderFooter?: (months: Grid.ICalendarMonth<Date>[]) => React.ReactNode
  }

  export interface ISingle extends IBase {
    /** Selection mode. Default `'single'`. */
    mode?: 'single'
    /** Controlled selection value. */
    selected?: ICalendarSelectionValue<'single'>
    /** Called when the selection changes. */
    onSelect?: (value: ICalendarSelectionValue<'single'>) => void
  }

  export interface IRange extends IBase {
    /** Selection mode. */
    mode: 'range'
    /** Controlled selection value. */
    selected?: ICalendarSelectionValue<'range'>
    /** Called when the selection changes. */
    onSelect?: (value: ICalendarSelectionValue<'range'>) => void
  }

  export interface IMulti extends IBase {
    /** Selection mode. */
    mode: 'multi'
    /** Controlled selection value. */
    selected?: ICalendarSelectionValue<'multi'>
    /** Called when the selection changes. */
    onSelect?: (value: ICalendarSelectionValue<'multi'>) => void
  }

  export interface IMultiRange extends IBase {
    /** Selection mode. */
    mode: 'multi-range'
    /** Controlled selection value. */
    selected?: ICalendarSelectionValue<'multi-range'>
    /** Called when the selection changes. */
    onSelect?: (value: ICalendarSelectionValue<'multi-range'>) => void
  }
}

